    if release.tag.trim_start_matches('v') == current {
        println!("Bastion {current} is the newest release");
        return Ok(());
    }
    let sums = release.fetch("SHA256SUMS").await?;
    let signature = release.fetch("SHA256SUMS.minisig").await?;
    signed(&sums, &String::from_utf8_lossy(&signature))?;
    let file = release.asset(&install);
    let bytes = release.fetch(&file).await?;
    let sums = String::from_utf8_lossy(&sums);
    let want =
        sum_of(&sums, &file).ok_or_else(|| format!("{file} is not in the release's sums"))?;
    if format!("{:x}", Sha256::digest(&bytes)) != want {
        return Err(format!(
            "{file} does not match its sum; nothing was changed"
        ));
    }
    replace(&install, &release, &bytes)?;
    println!(
        "Bastion {} is installed; start the server again to run it",
        release.tag
    );
    Ok(())
}

/// The newest release's tag, from where `/releases/latest` points.
async fn newest(http: &reqwest::Client) -> Result<String, String> {
    let answer = http
        .get(format!("{REPO}/releases/latest"))
            StackState::Running => return self.status(machine).map_err(failed),
            StackState::Taken { pid, compose_file } => {
                return Err(StartRefused::Taken { pid, compose_file });
            }
            StackState::Stopped => {}
        }
        let report = doctor::run(machine, engine, &self.checkout).await;
        if !report.ready() {
            return Err(StartRefused::Doctor { report });
        }
        let file = self.compose_file().display().to_string();
        machine
            .spawn(
                "iii",
                &["compose", "--up", "-f", &file],
                &self.checkout,
                &self.log,
            )
            .map_err(failed)?;
        let mut waited = Duration::ZERO;
        while waited < START_WAIT {
            if self.state(machine).map_err(failed)? == StackState::Running {
                return self.status(machine).map_err(failed);
            }
            tokio::time::sleep(START_POLL).await;
            waited += START_POLL;
        }
        Err(failed(format!(
            "the compose daemon did not appear within {}s; see {}",
            START_WAIT.as_secs(),
            self.log.display()
        )))
    }

    pub fn stop(&self, machine: &dyn Machine) -> Result<StackStatus, String> {
        let file = self.compose_file().display().to_string();
        let out = machine.run("iii", &["kill", "--compose", &file], Some(&self.checkout))?;
        if !out.success {
            return Err(format!("iii kill: {}", out.text.trim()));
        }
        self.status(machine)
    }
}

/// The port in an engine URL such as `ws://127.0.0.1:49160`.
pub fn port(url: &str) -> Option<u16> {
    url.rsplit(':').next()?.trim_end_matches('/').parse().ok()
}

